#!/bin/zsh
# launch-codex-resume.sh <SEAT> <TICKET> <PACKET_ABS> <SESSION_ID> <LOGTAG> — resume a Codex coding seat in its own session.
SEAT=$1; TICKET=$2; PACKET=$3; SID=$4; TAG=$5
A=/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine/.worktrees/all/dialectical-engine
LANE=/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine/.worktrees/fpd-s01/dialectical-engine
LOG=$A/.hermes/reports/free-public-debates/logs/seat-$SEAT-$TAG.log
PROMPT="You are RESUMED in your own session after the orchestrator ruled on your BLOCKED comment: read the newest orchestrator comment on your ticket first, then the DECISIONS section it names, then continue your packet from the step you stopped at. You are still seat $SEAT of the DebateAI heartbeat graph, mission free-public-debates, a coding (BUILD or FIX) node. Your packet is at this ABSOLUTE path - read it FIRST and in full, then the COMMON.md it names, then ONLY the paths the packet allows, at the lines it names: $PACKET . Skills are markdown files for you: read each one the packet's line 4 names (COMMON section 1 says where they live; cite only the .claude path of a heartbeat skill). Order of work: (1) read those skills; (2) READ the comments on your ticket $TICKET with: ~/.local/bin/hermes kanban --board free-public-debates show $TICKET --json ; (3) post your CLAIM comment (COMMON section 2) carrying the re-measured base frame; (4) do the packet's work in the lane - RED first on every step - committing on your slice branch only when the cluster command is green three runs; (5) file your self-report; (6) post READY on the ticket in the eight-line shape, opening with SKILLS LOADED:, and print the same handoff as your final message. Never push, never merge, never touch a path outside your allowed list, never touch the no-touch listeners or any live database, open nothing on the desktop, do not sub-delegate. If the packet is wrong or you are blocked, post BLOCKED on the ticket and stop."
cd $LANE && caffeinate -s -i /Users/vladmihaimiron/.local/bin/codex exec -c model='"gpt-5.6-sol"' -c sandbox_mode='"danger-full-access"' resume $SID "$PROMPT" </dev/null > $LOG 2>&1
echo "CODEX SEAT $SEAT EXIT rc=$? $(date '+%H:%M:%S')" >> $LOG; grep -n "session id" $LOG | head -1; tail -60 $LOG
